import { useEffect, useRef } from "react";

/**
 * An exported animated SVG used as a case-study thumbnail (generated by
 * `npm run thumbs`). Its CSS animations sit paused on the first frame. When
 * `playing` turns true they play forward once and hold the last frame; when it
 * turns false they play backward from wherever they are and stop on the first.
 */
export function AnimatedThumb({
  markup,
  width,
  height,
  playing,
  still = false,
  speed = 1,
  className = "",
}: {
  /** Inner SVG markup (everything inside <svg>). */
  markup: string;
  width: number;
  height: number;
  playing: boolean;
  /** Show the finished frame and ignore `playing` (touch / mobile layouts). */
  still?: boolean;
  /** Playback speed multiplier (0.5 = half speed). */
  speed?: number;
  className?: string;
}) {
  const ref = useRef<SVGSVGElement>(null);
  const started = useRef(false);

  // Reduced motion: no playback, just show the finished artwork.
  useEffect(() => {
    if (!window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    ref.current?.getAnimations({ subtree: true }).forEach((a) => a.finish());
  }, []);

  // Mobile / touch: rest on the last frame. Back to desktop: return to the first.
  useEffect(() => {
    const svg = ref.current;
    if (!svg) return;
    if (still) {
      started.current = true;
      svg.getAnimations({ subtree: true }).forEach((a) => {
        a.pause();
        a.currentTime = Number(a.effect?.getComputedTiming().endTime ?? 0);
      });
    } else if (started.current && !playing) {
      svg.getAnimations({ subtree: true }).forEach((a) => {
        a.pause();
        a.currentTime = 0;
      });
    }
  }, [still]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const svg = ref.current;
    if (still || !svg || (!playing && !started.current)) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    started.current = true;
    for (const anim of svg.getAnimations({ subtree: true })) {
      // play() on an animation already sitting at the end it's heading for
      // would rewind it to the other end first, so leave those alone.
      const t = Number(anim.currentTime ?? 0);
      const end = Number(anim.effect?.getComputedTiming().endTime ?? 0);
      anim.playbackRate = (playing ? 1 : -1) * speed;
      if (playing ? t >= end : t <= 0) anim.pause();
      else anim.play();
    }
  }, [playing, still, speed]);

  return (
    <svg
      ref={ref}
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="xMidYMid slice"
      aria-hidden="true"
      focusable="false"
      className={`anim-thumb block size-full ${className}`}
      dangerouslySetInnerHTML={{ __html: markup }}
    />
  );
}
